{
  "items": [
    {
      "name": "Pi.card_Icc",
      "module_name": "Mathlib.Data.Pi.Interval",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : ι → Type u_2} [inst : Fintype ι] [inst_1 : DecidableEq ι] [inst_2 : (i : ι) → DecidableEq (α i)]\n  [inst_3 : (i : ι) → PartialOrder (α i)] [inst_4 : (i : ι) → LocallyFiniteOrder (α i)] (a b : (i : ι) → α i),\n  (Finset.Icc a b).card = ∏ i, (Finset.Icc (a i) (b i)).card"
    },
    {
      "name": "Pi.card_uIcc",
      "module_name": "Mathlib.Data.Pi.Interval",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : ι → Type u_2} [inst : Fintype ι] [inst_1 : DecidableEq ι] [inst_2 : (i : ι) → DecidableEq (α i)]\n  [inst_3 : (i : ι) → Lattice (α i)] [inst_4 : (i : ι) → LocallyFiniteOrder (α i)] (a b : (i : ι) → α i),\n  (Finset.uIcc a b).card = ∏ i, (Finset.uIcc (a i) (b i)).card"
    },
    {
      "name": "Pi.card_Iic",
      "module_name": "Mathlib.Data.Pi.Interval",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : ι → Type u_2} [inst : Fintype ι] [inst_1 : DecidableEq ι] [inst_2 : (i : ι) → DecidableEq (α i)]\n  [inst_3 : (i : ι) → PartialOrder (α i)] [inst_4 : (i : ι) → LocallyFiniteOrderBot (α i)] (b : (i : ι) → α i),\n  (Finset.Iic b).card = ∏ i, (Finset.Iic (b i)).card"
    },
    {
      "name": "Finset.card_Iic_prod",
      "module_name": "Mathlib.Order.Interval.Finset.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : Preorder α] [inst_1 : Preorder β] [inst_2 : LocallyFiniteOrderBot α]\n  [inst_3 : LocallyFiniteOrderBot β] [inst_4 : DecidableLE (α × β)] (x : α × β),\n  (Finset.Iic x).card = (Finset.Iic x.1).card * (Finset.Iic x.2).card"
    },
    {
      "name": "DFinsupp.card_Icc",
      "module_name": "Mathlib.Data.DFinsupp.Interval",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : ι → Type u_2} [inst : DecidableEq ι] [inst_1 : (i : ι) → DecidableEq (α i)]\n  [inst_2 : (i : ι) → PartialOrder (α i)] [inst_3 : (i : ι) → Zero (α i)] [inst_4 : (i : ι) → LocallyFiniteOrder (α i)]\n  (f g : Π₀ (i : ι), α i), (Finset.Icc f g).card = ∏ i ∈ f.support ∪ g.support, (Finset.Icc (f i) (g i)).card"
    }
  ]
}
